mapper.select:
select id,filing_no,change_type,apply_unit,apply_dept,apply_user,ticket_status,ticket_creat_type,receiver_time
from idevelop_device_change where is_deleted = 0

    and filing_no = #{deviceChange.filingNo}


    and change_type = #{deviceChange.changeType}


    and ticket_status = #{deviceChange.ticketStatus}


    and apply_dept = #{deviceChange.applyDept}


    and receiver_time >= #{deviceChange.startDate} and receiver_time <= #{deviceChange.startDate}


    and change_code = #{deviceChange.changeCode}

select idc.*
from idevelop_device_change idc left join idevelop_device_change_list idcl on idc.id = idcl.change_id

    idc.is_deleted = 0
    
        AND idcl.device_code LIKE CONCAT('%', #{deviceChange.deviceCode}, '%')
    
    
        AND idc.apply_unit = #{deviceChange.applyUnit}
    
    
        AND idc.apply_dept = #{deviceChange.applyDept}
    
    
        AND idc.change_type = #{deviceChange.changeType}
    
    
        AND idc.ticket_creat_type = #{deviceChange.ticketCreatType}
    
    
        AND idc.apply_user_name = #{deviceChange.applyUserName}
    
    
        AND idc.region_code LIKE CONCAT(#{deviceChange.regionCode}, '%')
    
    
        AND idc.receiver_time >= #{deviceChange.startDate}
        AND idc.receiver_time <= #{deviceChange.endDate}
    
    GROUP BY idc.id ORDER BY idc.create_time DESC
